#!/usr/bin/env node
// Lints board .dc.html files against references/board-anatomy.md.
// Usage: node lint_boards.mjs <dir-or-file> [--after-only] [--manifest <out.json>]
// --manifest writes every board's screen ID, features, states (entry, data) and controls for the app harness.
// Cover, index and *-workflow pages are not boards and are skipped.
// shortcut: regex checks on source text, no DOM; upgrade to a DOM pass if boards get generated by script.
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join, basename } from 'node:path';
import { createHash } from 'node:crypto';

const args = process.argv.slice(2);
const afterOnly = args.includes('--after-only');
const mi = args.indexOf('--manifest');
const manifestOut = mi >= 0 ? args[mi + 1] : null;
const target = args.find((a, i) => !a.startsWith('--') && !(mi >= 0 && i === mi + 1));
if (!target) {
  console.log('usage: node lint_boards.mjs <dir-or-file> [--after-only] [--manifest <out.json>]');
  process.exit(0);
}

const files = statSync(target).isDirectory()
  ? readdirSync(target).filter((f) => /\.dc\.html$/.test(f) && !/^(Main|Index)\./.test(f) && !/-workflow\.dc\.html$/.test(f)).map((f) => join(target, f))
  : [target];

const count = (s, re) => (s.match(re) || []).length;
const attr = (tag, name) => (tag.match(new RegExp(`\\s${name}="([^"]*)"`)) || [])[1];
const text = (h) => h.replace(/<[^>]+>/g, '').replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&#160;|&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const MAX_STATES = 6;
const manifest = [];
let bad = 0;

for (const f of files) {
  const s = readFileSync(f, 'utf8');
  const errs = [];
  const notes = count(s, /class="note[ "]/g);
  if (notes < 2) errs.push(`callout notes: ${notes} (need >= 2, bold trigger + result)`);
  if (!/class="note[^"]*"[^>]*><b>/.test(s)) errs.push('no note starts with a <b>trigger</b>');
  for (const card of ['What it must show', 'Motion', 'Stories', 'Where it lives']) {
    if (!s.includes(card)) errs.push(`aside card missing: ${card}`);
  }
  if (!/<b>Extends:<\/b>/.test(s)) errs.push('header lacks Extends:');
  if (!/Lives in:/.test(s)) errs.push('header lacks Lives in:');
  const storyStats = count(s, /class="stat (built|partial|new)"/g);
  const storyIds = count(s, /class="sid"/g);
  if (storyIds === 0) errs.push('no stories');
  else if (storyStats !== storyIds) errs.push(`stories ${storyIds} but status pills ${storyStats}`);
  const partialStories = count(s, /class="stat partial"/g);
  const gaps = count(s, /class="gap"/g);
  if (partialStories > gaps) errs.push(`${partialStories} Partial stories but ${gaps} Exists/Missing lines`);
  const partTags = count(s, /class="parttag"/g);
  const partNotes = count(s, /class="note pn"/g);
  if (partTags > partNotes) errs.push(`${partTags} PARTIAL tags but ${partNotes} Exists:/Missing: notes`);
  const newStories = count(s, /class="stat new"/g);
  const newTags = count(s, /class="newtag"/g);
  if (newStories > 0 && newTags === 0) errs.push('New stories but no NEW tag in the window');
  if (partialStories > 0 && partTags === 0) errs.push('Partial stories but no PARTIAL tag in the window');
  const hasToggle = /class="vw"/.test(s);
  if (afterOnly && hasToggle) errs.push('Before/After toggle present but After only was chosen');
  if (!afterOnly && !hasToggle) errs.push('no Before/After toggle (pass --after-only if the user chose After only)');
  if (/lorem ipsum/i.test(s)) errs.push('lorem ipsum');

  // Rule 17: screen and feature IDs (anatomy section 9).
  const screen = (s.match(/class="board"[^>]*data-screen="([^"]+)"/) || [])[1];
  if (!screen) errs.push('board root lacks data-screen="S.."');
  const sids = [...s.matchAll(/class="sid">([^<]*)</g)].map((m) => m[1].trim());
  const badIds = sids.filter((id) => !/^[A-Z]{1,4}\d{2,4}$/.test(id));
  if (badIds.length) errs.push(`story IDs not feature IDs: ${badIds.join(', ')}`);
  for (const m of s.matchAll(/<[a-z]+\b[^>]*class="(?:new|part)[ "][^>]*>/g)) {
    const fid = attr(m[0], 'data-feature');
    if (!fid) errs.push(`NEW/PARTIAL marker without data-feature: ${m[0].slice(0, 60)}`);
    else if (!sids.includes(fid)) errs.push(`marker feature ${fid} not in Stories`);
  }

  // Rule 15: States card, entry + data per state, cap, switch buttons, controls.
  const states = [...s.matchAll(/<li class="state"[^>]*data-state="([^"]+)"[^>]*>([\s\S]*?)<\/li>/g)].map((m) => {
    const e = text(m[2]).match(/Entry:\s*(.*?)\s*·\s*Data:\s*(.*)$/);
    return { state: m[1], entry: e ? e[1] : '', data: e ? e[2] : '' };
  });
  if (!states.length) errs.push('no States card rows (li.state with Entry: and Data:)');
  if (states.length > MAX_STATES) errs.push(`${states.length} states (max ${MAX_STATES}): split the board`);
  for (const st of states) {
    if (!st.entry) errs.push(`state ${st.state}: no Entry click path`);
    else if (/\?(view|raw|state)\b|#\/\S*\?/i.test(st.entry)) errs.push(`state ${st.state}: Entry is a URL shortcut, not a click path`);
    if (!st.data) errs.push(`state ${st.state}: no Data source`);
  }
  const controls = [];
  const later = [];
  for (const m of s.matchAll(/<(?:button\b[^>]*|[a-z]+\b[^>]*role="button"[^>]*)>/g)) {
    const t = m[0];
    const ds = attr(t, 'data-state');
    const does = attr(t, 'data-does');
    const lt = attr(t, 'data-later');
    if (ds) {
      if (!states.some((x) => x.state === ds)) errs.push(`switch button data-state="${ds}" has no States row`);
    } else if (does) {
      const fid = attr(t, 'data-feature');
      if (!fid) errs.push(`control "${does}" lacks data-feature`);
      else if (!sids.includes(fid)) errs.push(`control "${does}" feature ${fid} not in Stories`);
      controls.push({ does, feature: fid });
    } else if (lt) later.push(lt);
    else errs.push(`control without data-does / data-later / data-state: ${t.slice(0, 70)}`);
  }
  const laterTags = count(s, /class="latertag"/g);
  if (later.length > laterTags) errs.push(`${later.length} data-later controls but ${laterTags} LATER tags`);
  // hash: the harness re-tests a state when its board changed after it passed.
  manifest.push({ board: basename(f), hash: createHash('sha256').update(s).digest('hex').slice(0, 16), screen, features: sids, states, controls, later });

  if (errs.length) {
    bad++;
    console.log(`FAIL ${basename(f)}`);
    errs.forEach((e) => console.log(`  - ${e}`));
  } else console.log(`ok   ${basename(f)}`);
}
console.log(`${files.length - bad}/${files.length} boards pass`);
if (manifestOut) {
  writeFileSync(manifestOut, JSON.stringify(manifest, null, 2));
  console.log(`manifest: ${manifest.length} boards, ${manifest.reduce((n, b) => n + b.states.length, 0)} states -> ${manifestOut}`);
}
process.exit(bad ? 1 : 0);
